import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int sumEven = 0;
        int productOdd = 1;

        // Lambda to process each element
        java.util.function.IntConsumer process = num -> {
            if (num % 2 == 0) {
                // Even: add to sumEven
                sumEven += num;
            } else {
                // Odd: multiply to productOdd
                productOdd *= num;
            }
        };

        // Apply lambda to each element
        for (int num : arr) {
            process.accept(num);
        }

        int result = sumEven - productOdd;
        System.out.println(result);
    }
}
